        private void Check(string id, bool golden, int steps, int[] expected)
        { try { Verify(id, golden, steps, expected); } catch (AssertionException error) { failures.Add(error.Message); } }
        private static void Verify(string id, bool golden, int steps, int[] expected)
        {
            var relic = new OwnedRelic(RelicCatalog.All.Single(r=>r.Id==id), golden ? ChromaKind.Golden : ChromaKind.None);
            var cards=Enumerable.Range(0,10).Select(_=>new CardDefinition("probe","Carta",1,6,5,1)).ToArray();
            var enemy=new EnemyState("e",new EnemyDefinition("fixture","Objetivo","wraith",1000),1,1000);
            typeof(EnemyState).GetProperty("Intent").SetValue(enemy,new EnemyIntent(IntentKind.Attack,5));
            var state=new CombatState(HeroDefinition.OriginalFor(HeroKind.Warrior),cards,42,50,new[]{enemy},relics:new[]{relic});
            for(var step=1;step<=steps;step++)
            {
                if(step==2) { typeof(EnemyState).GetProperty("Intent").SetValue(enemy,new EnemyIntent(IntentKind.Attack,5)); state.EndTurn(); }
                else Assert.That(state.PlayCard(0),Is.True,id);
            }
            var actual=new[] {state.Hp,state.Block,state.Strength,state.Mana,state.ManaMaximum,enemy.Hp,enemy.Block,state.Hand.Count,state.DrawCount,state.DiscardCount,state.HpLostCombat,state.GoldEarned,
                enemy.Statuses[StatusKind.Poison],enemy.Statuses[StatusKind.Marked],enemy.Statuses[StatusKind.Weak],enemy.Statuses[StatusKind.Vulnerable],enemy.Statuses[StatusKind.Frail],enemy.Statuses[StatusKind.Entangled],enemy.Statuses[StatusKind.Strength],enemy.Statuses[StatusKind.Blades],enemy.Statuses[StatusKind.Fuse],enemy.Statuses[StatusKind.Fire],enemy.Statuses[StatusKind.Water],enemy.Statuses[StatusKind.Earth],enemy.Statuses[StatusKind.Air],enemy.Statuses[StatusKind.Frozen]};
            Assert.That(actual,Is.EqualTo(expected), id+" golden="+golden+" step="+steps);
        }
    }
}
